public class Order
{
    public Guid Id { get; set; }
    public string ShipToName { get; set; } = string.Empty;
    public DateTime UpdatedAtUtc { get; set; }

    [Timestamp]
    public byte[] RowVersion { get; set; } = Array.Empty<byte>();
}

[HttpPut("{id:guid}")]
public async Task<IActionResult> Update(Guid id, UpdateOrderDto dto)
{
    var order = await _db.Orders.FindAsync(id);
    if (order is null) return NotFound();

    order.ShipToName = dto.ShipToName;
    order.ShippedAt = DateTime.UtcNow;

    try
    {
        await _db.SaveChangesAsync();
    }
    catch (DbUpdateConcurrencyException)
    {
        return Conflict(new ApiErrorResponse
        {
            Status = StatusCodes.Status409Conflict,
            Title = "The record was modified by another user.",
            Code = "CONCURRENT_MODIFICATION",
            Detail = "Refresh the record, apply your changes again, and retry.",
            Errors = new()
            {
                ["Order"] = new[] { "The current version no longer matches the server." }
            }
        });
    }

    return NoContent();
}
